logger = BackgroundLogger.Instance()

try:
    from taf.wts.runner import runner
    from taf.transport.ssh import ssh
except ImportError:
    logger.warn('TAF libraries unavailable for Airphone operations. Ignore if the keywords are not used')


default_egate_edaemon_ports = [20000, 22222]


class AirphoneNSA(iphy):
    """Airphone NSA"""

    def __init__(self, device_details, device_name, dut, rat, **kwargs):
        self.runner = runner()
        self.taf_ssh = ssh()
        self.ue_type = "airphone"
        self.device_name = device_name
        self.relative_cfg_path = os.path.join(ConfigHandler.config['common_resources_path'])
        # self.egate_alias = None
        # self.alias = 'LTEemu'
        self.alias = 'WTSemu'
        setup_wtssim = kwargs.pop("setup_wtssim", True)
        self.attach_flag = kwargs.pop("attach", True)
        self.timeout = kwargs.get("timeout", 120)
        self.te_id = TeId(dut, rat)
        self.rat = rat
        self.store = Store()
        self.config = ConfigHandler.get_config()
        # self.attach_arguments = kwargs
        self.ue_ids = kwargs.get("ue_ids", "1")
        should_be_onair = kwargs.pop('should_be_onair', False)
        self.device_details = device_details
        self.is_enb_external = False
        admin_alias = kwargs.get("admin_alias", None)
        if setup_wtssim:
            self._retry_on_failure_setup_wtssim(device_details, should_be_onair, admin_alias)

    def attach(self, verify_teid=False, call_type="data"):
        if self.attach_flag:
            if verify_teid:
                initial_iwf_value = self.te_id.get_te_id()
            # self._get_attach_arguments()
            # self.runner.ue_attach(id=self.ue_ids, profile=1)
            self.runner.ue_attach(id=self.ue_ids, profile=self.device_details.get('profile', 1))
            # phycell_id=50 nrsrp=127 event=B1_NR
            # if ConfigHandler.config['rat_env'] ==  ['lte', 'wcdma', 'gsm', '5g']:
            time.sleep(5)
            self.runner.read_wtsemu_output_until_re(expected='UE IS ACTIVE', timeout=self.timeout)
            if self.is_enb_external:
                try:
                    self.runner.ue_measurement_send(
                        id=self.ue_ids,
                        nr_cgi_cell_ident=self.device_details["nr_cgi_cell_ident"],
                        nr_cgi_plmn_ident_info_id=self.device_details["nr_cgi_plmn_ident_info_id"],
                        nr_cgi_plmns_ident=self.device_details["nr_cgi_plmns_ident"],
                        phycell_id=self.device_details.get("phycell_id", 50),
                        nrsrp=self.device_details.get("nrsrp", 127),
                        event=self.device_details.get("event", "B1_NR"))
                except Exception as e:
                    raise Exception("Failed during attach ue_measurement_send, failure reason is {}".format(e))
            else:
                self.runner.enb_ue_dc_start(ue=self.ue_ids,
                                            target_gnb=self.device_details.get("gnb", 2),
                                            target_cells=self.device_details.get("target_cells", 2),
                                            bearer=self.device_details.get("bearer_id", 2),
                                            type=self.device_details.get("type", 'split_scg'))
                self.runner.read_wtsemu_output_until_re(expected="reported Successful RA", timeout=self.timeout)
            time.sleep(5)
            if verify_teid:
                self.te_id.check_iwf_value_increased(initial_iwf_value)

    def detach(self, **kwargs):
        self.runner.ue_detach(id=self.ue_ids)
        time.sleep(5)

    def configure_ue(self, **kwargs):
        kwargs.pop('5g')
        command = kwargs.pop('command')
        # timeout = kwargs.pop('timeout', 10)
        runner_keyword = getattr(self.runner, command)
        output = runner_keyword(**kwargs)
        time.sleep(2)
        return output

    def call_teardown(self):
        self.taf_ssh.disconnect()
        # self.wtssim.teardown_all_aliases_for_edaemon()

    def check_if_enb_is_external(self, lua_file_path):
        try:
            with open(lua_file_path) as f:
                lines = f.readlines()
            for line in lines:
                if "set_enb type=external" in line:
                    self.is_enb_external = True
                    return True
            return False
        except Exception as e:
            raise "Failed while read {}. Received exception {}".format(lua_file_path, e)

    def _retry_on_failure_setup_wtssim(self, device_details, should_be_onair, admin_alias):
        attempt = 1
        while attempt <= 3:
            self._setup_wtssim(device_details)
            admin_alias = _setup_oam_ops(alias=admin_alias)
            if should_be_onair:
                try:
                    bts_status = CellOperations().verify_bts_status(req_rat=self.rat,
                                                                    should_be_onair=should_be_onair,
                                                                    alias=admin_alias)
                    if bts_status:
                        break
                except Exception as e:
                    logger.warn("Attempt {} :: Expected rat {} is not onAir : {}".format(attempt, self.rat, e))
                    self._teardown_wtssim(device_details)
                finally:
                    attempt += 1
            else:
                break
        else:
            raise BtsNotOnAirException

    def _setup_wtssim(self, device_details):
        hostname = device_details['remote_ip']
        username = device_details['remote_user']
        password = device_details['remote_password']
        airphone_bin_path = device_details.get('airphone_bin_path', '/opt/iphy/EPC_SIM_AP')
        self.taf_ssh.connect_to(hostname=hostname, username=username, password=password,
                                alias=self.alias)
        lua_files_dict = self._get_lua_file_and_ports(device_details)
        for lua_file_name, ports in list(lua_files_dict.items()):
            local_lua_file = os.path.join(self.relative_cfg_path, lua_file_name)
            remote_lua_file = os.path.join(airphone_bin_path, lua_file_name)
            if not os.path.exists(local_lua_file):
                raise Exception('Lua File {} Does not Exist'.format(local_lua_file))
            self.taf_ssh.upload_file(local_lua_file, remote_lua_file, connection=self.alias)
            logger.info("local lua file: {}".format(local_lua_file))
            egate_port, edaemon_ports = ports
            logger.debug('ports egate: {} edaemon: {}'.format(str(egate_port), str(edaemon_ports)))
            self.runner.configure_wtsemu_egate(egate_ssh_alias=self.alias,
                                               directory_path=airphone_bin_path,
                                               port=egate_port)
            self._setup_edaemons(hostname=hostname, egate_port=egate_port,
                                 airphone_bin_path=airphone_bin_path,
                                 ports=edaemon_ports)
            self.runner.start_wtsemu(egate_console_ip=hostname, egate_port=egate_port)
            self.runner.configure(file=lua_file_name)
            time.sleep(5)
            self.runner.read_wtsemu_output_until_re(expected='CHANGE STATE: ACTIVE - SimMode is ready now',
                                                    timeout=self.timeout)
            time.sleep(5)
            if not self.check_if_enb_is_external(local_lua_file):
                # self.runner.enb_x2_link_up(enb=1, target=2)
                self.runner.enb_x2_link_up(enb=self.device_details.get('enb', 1),
                                           target=self.device_details.get('target', 2))
                time.sleep(5)
                self.runner.read_wtsemu_output_until_re(expected='ENB-1: X2AP Link with [EG]NB-2 .*(\\n)?? (\\n)??i'
                                                                 '(\\n)??s(\\n)?? (\\n)??u(\\n)??p',
                                                        timeout=self.timeout)

    def _teardown_wtssim(self, device_details):
        lua_files_dict = self._get_lua_file_and_ports(device_details)
        for lua_file_name, ports in list(lua_files_dict.items()):
            local_lua_file = os.path.join(self.relative_cfg_path, lua_file_name)
            if not os.path.exists(local_lua_file):
                raise Exception('Lua File {} Does not Exist'.format(local_lua_file))
            logger.info("local lua file: {}".format(local_lua_file))
            egate_port, edaemon_ports = ports
            logger.debug('ports egate: {} edaemon: {}'.format(str(egate_port), str(edaemon_ports)))
            self.runner.kill_wtsemu_egate(egate_port=egate_port, connection=self.alias)
            self.runner.kill_wtsemu_edaemon(edaemon_port=edaemon_ports, connection=self.alias)
            self.runner.stop_wtsemu()

    def _data_start(self, profile, profile_params, ue_ids):
        # Remove unwanted profile params
        # bearer_ue_param ue=1 id=9 scg_ul_dist_percent=100
        # if ConfigHandler.config['rat_env'] == ['lte', 'wcdma', 'gsm', '5g']:
        if self.is_enb_external:
            try:
                self.runner.bearer_ue_param(ue=ue_ids,
                                            id=self.device_details.get("bearer_id", 2),
                                            scg_ul_dist_percent=self.device_details.get(
                                                "scg_ul_dist_percent", 100))
            except Exception:
                raise Exception("Make sure 'scg_ul_dist_percent' is defined under "
                                "testline_config.json->ue_devices for Airphone type External")
        self.runner.trf_data_start(**profile_params)
        self.store.add((ue_ids, profile_params["id"]), alias=profile)

    def _data_stop(self, profile):
        ue_ids, bearer_id = self.store.get(alias=profile)
        # self.runner.trf_data_stop(ue=ue_ids, id=bearer_id, alias=self.alias)
        self.runner.trf_data_stop(ue=ue_ids, id=bearer_id)
        self.store.remove(alias=profile)

    def _retreive_ueip(self, ue_id):
        # output = self.runner.ue_disp(id=ue_id, at='ue', alias=self.alias)
        output = self.runner.ue_disp(id=ue_id, at=self.device_details.get('ue_disp_at', 'ue'),
                                     alias=self.alias)
        return output["UE Ip"]

    def _retreive_natip(self, ue_id):
        # output = self.runner.ue_disp(id=ue_id, at='ue', alias=self.alias)
        output = self.runner.ue_disp(id=ue_id, at=self.device_details.get('ue_disp_at', 'ue'),
                                     alias=self.alias)
        return output['UE NAT Ip']

    def _setup_edaemons(self, hostname, egate_port, airphone_bin_path, ports):
        port_list = []
        if not isinstance(ports, list):
            port_list.append(ports)
        else:
            port_list = ports
        edaemon_alias_list = []
        for index, edaemon_port in enumerate(port_list):
            edaemon_alias = str(edaemon_port) + "_" + str(index)
            time.sleep(2)
            self.runner.configure_wtsemu_edaemon(edaemon_ssh_alias=self.alias,
                                                 directory_path=airphone_bin_path,
                                                 port=edaemon_port)
            time.sleep(2)
            self.runner.start_wtsemu(egate_console_ip=hostname, egate_port=egate_port)
            edaemon_alias_list.append(edaemon_alias)
        logger.debug("All edaemon alias list{}".format(edaemon_alias_list))
        return edaemon_alias_list

